declare(strict_types=1);

namespace App\Tests\Unit;

use App\Modules\Blog\Domain\Blog;
use App\Modules\Blog\Domain\BlogRules;
use App\Modules\Blog\Domain\BlogStatus;
use App\Shared\Domain\Exception\ConflictException;
use App\Shared\Domain\Exception\ValidationException;
use App\Shared\Domain\Uuid;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Blog domain: creation/normalisation, validation per field, updates, lifecycle state machine, soft delete.
 */
final class BlogDomainTest extends TestCase
{
    public function testCreateNormalisesAndRecordsEvent(): void
    {
        $e = $this->entity();
        self::assertSame(1, $e->version());
        self::assertFalse($e->isDeleted());
        $events = $e->pullEvents();
        self::assertCount(1, $events);
        self::assertSame(Blog::EVENT_CREATED, $events[0]['type']);
        self::assertSame($e->id, $events[0]['payload']['id']);
        self::assertSame([], $e->pullEvents(), 'events are drained');
        foreach (BlogRules::FIELDS as $field) {
            self::assertArrayHasKey($field, $e->values());
        }
    }

    public function testRequiredFieldsAreValidated(): void
    {
        try {
            BlogRules::normalize([], true);
            self::fail('ValidationException expected');
        } catch (ValidationException $e) {
            foreach (['title'] as $field) {
                self::assertArrayHasKey($field, $e->errors(), $field);
            }
        }
    }
    public function testInvalidValuesAreRejectedPerField(): void
    {
        try {
            BlogRules::normalize([
                'title' => str_repeat('x', 256),
                'description' => str_repeat('x', 501),
                'due_on' => '2026-13-45',
                'owner_id' => 'not-a-uuid',
            ], false);
            self::fail('ValidationException expected');
        } catch (ValidationException $e) {
            foreach (['title', 'description', 'due_on', 'owner_id'] as $field) {
                self::assertArrayHasKey($field, $e->errors(), $field);
            }
        }
    }
    public function testUpdateReportsChangesAndRecordsEvent(): void
    {
        $e = $this->entity();
        $e->pullEvents();
        $value = 'Updated title ' . bin2hex(random_bytes(4));
        $changes = $e->update(['title' => $value, 'unknown_field' => 'ignored']);
        self::assertArrayHasKey('title', $changes);
        self::assertSame(Blog::EVENT_UPDATED, $e->pullEvents()[0]['type']);
        self::assertSame([], $e->update(['title' => $value]), 'no-op update');
    }
    public static function transitions(): iterable
    {
        $allowed = [
            'draft' => ['active', 'archive'],
            'active' => ['archive'],
            'archive' => [],
        ];
        foreach (BlogStatus::cases() as $from) {
            foreach (BlogStatus::cases() as $to) {
                yield $from->value . '→' . $to->value => [$from, $to, in_array($to->value, $allowed[$from->value], true)];
            }
        }
    }

    #[DataProvider('transitions')]
    public function testStateMachineMatrix(BlogStatus $from, BlogStatus $to, bool $expected): void
    {
        self::assertSame($expected, $from->canTransitionTo($to));
        if (!$expected) {
            try {
                $from->assertTransitionTo($to);
                self::fail('Expected ConflictException');
            } catch (ConflictException $e) {
                self::assertSame('invalid_transition', $e->errorCode());
                self::assertSame(409, $e->httpStatus());
            }
        }
    }

    public function testTerminalStateIsReadOnly(): void
    {
        $e = $this->entity();
        self::assertSame(BlogStatus::initial(), $e->status());
        $from = $e->changeStatus(BlogStatus::Archive, 'done');
        self::assertSame(BlogStatus::initial(), $from);
        self::assertTrue($e->status()->isTerminal());
        self::assertSame([], $e->status()->allowedTransitions());
        $this->expectException(ConflictException::class);
        $e->update([]);
    }

    public function testStatusChangeRecordsEvent(): void
    {
        $e = $this->entity();
        $e->pullEvents();
        $e->changeStatus(BlogStatus::Active);
        $events = $e->pullEvents();
        self::assertSame(Blog::EVENT_STATUS_CHANGED, $events[0]['type']);
        self::assertSame('active', $events[0]['payload']['to']);
    }

    public function testDeleteIsSoftAndFinal(): void
    {
        $e = $this->entity();
        $e->markDeleted();
        self::assertTrue($e->isDeleted());
        self::assertNotNull($e->toRow()['deleted_at']);
        $this->expectException(ConflictException::class);
        $e->markDeleted();
    }

    private function entity(): Blog
    {
        return Blog::create(Uuid::v7(), Uuid::v7(), [
            'title' => 'Sample title ' . bin2hex(random_bytes(4)),
            'description' => 'Sample description ' . bin2hex(random_bytes(4)),
            'due_on' => '2026-12-31',
            'owner_id' => Uuid::v7(),
        ], Uuid::v7());
    }
}
